-- Synthetic fixtures only; never run this on production.
\set ON_ERROR_STOP on
begin;
select set_config('request.jwt.claim.sub','',true);
create temp table lot_fixture(a uuid,b uuid,ma uuid,mb uuid,staff uuid,batch uuid,transfer uuid,command uuid);
insert into lot_fixture select gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid();
grant select on lot_fixture to authenticated;
insert into public.branches(id,name) select a,'Lot test A' from lot_fixture union all select b,'Lot test B' from lot_fixture;
insert into auth.users(id,email) select ma,ma::text||'@lot.invalid' from lot_fixture union all select mb,mb::text||'@lot.invalid' from lot_fixture union all select staff,staff::text||'@lot.invalid' from lot_fixture;
insert into public.users(id,branch_id,role,status) select ma,a,'manager','active' from lot_fixture union all select mb,b,'manager','active' from lot_fixture union all select staff,a,'staff','active' from lot_fixture on conflict(id) do update set branch_id=excluded.branch_id,role=excluded.role,status=excluded.status;
insert into public.stock_batches(id,branch_id,product,category,unit,qty,received_date,expiry_date,lot_number,status) select batch,a,'Lot test rice','Dry','kg',5,current_date,current_date+14,'SOURCE-LOT','active' from lot_fixture;
select set_config('request.jwt.claim.sub',mb::text,true) from lot_fixture;
set local role authenticated;
insert into public.stock_transfers(id,from_branch_id,to_branch_id,product,category,unit,qty,requested_by,status) select transfer,a,b,'Lot test rice','Dry','kg',3,mb,'requested' from lot_fixture;
do $$declare f record;begin select * into f from lot_fixture;
 begin perform public.post_lot_transfer(f.b,f.transfer,f.command,'send',jsonb_build_array(jsonb_build_object('id',f.batch,'qty',3)),'Wrong side');raise exception 'Destination dispatched';exception when insufficient_privilege then null;end;
end $$;
reset role;
select set_config('request.jwt.claim.sub',ma::text,true) from lot_fixture;
set local role authenticated;
do $$declare f record;begin select * into f from lot_fixture;
 begin update public.stock_transfers set status='sent' where id=f.transfer;raise exception 'Unallocated dispatch allowed';exception when unique_violation then null;end;
 begin perform public.post_lot_transfer(f.a,f.transfer,gen_random_uuid(),'send',jsonb_build_array(jsonb_build_object('id',f.batch,'qty',2)),'Bad sum');raise exception 'Partial allocation allowed';exception when raise_exception then if sqlerrm='Partial allocation allowed' then raise;end if;end;
 if (select remaining_qty from public.stock_batches where id=f.batch)<>5 then raise exception 'Failed dispatch leaked stock';end if;
 perform public.post_lot_transfer(f.a,f.transfer,f.command,'send',jsonb_build_array(jsonb_build_object('id',f.batch,'qty',3)),'Dispatch reviewed');
 perform public.post_lot_transfer(f.a,f.transfer,f.command,'send',jsonb_build_array(jsonb_build_object('id',f.batch,'qty',3)),'Dispatch reviewed');
 if (select remaining_qty from public.stock_batches where id=f.batch)<>2 or (select count(*) from public.inventory_transfer_lots where transfer_id=f.transfer)<>1 then raise exception 'Dispatch retry duplicated stock';end if;
end $$;
reset role;
select set_config('request.jwt.claim.sub',mb::text,true) from lot_fixture;
set local role authenticated;
do $$declare f record;l uuid;c uuid:=gen_random_uuid();begin select * into f from lot_fixture;select id into l from public.inventory_transfer_lots where transfer_id=f.transfer;
 perform public.post_lot_transfer(f.b,f.transfer,c,'receive',jsonb_build_array(jsonb_build_object('id',l,'qty',2)),'One kg missing in transit');
 perform public.post_lot_transfer(f.b,f.transfer,c,'receive',jsonb_build_array(jsonb_build_object('id',l,'qty',2)),'One kg missing in transit');
 if (select count(*) from public.stock_batches where transfer_lot_id=l)<>1 or not exists(select 1 from public.stock_batches where transfer_lot_id=l and branch_id=f.b and remaining_qty=2 and expiry_date=current_date+14 and lot_number='SOURCE-LOT') then raise exception 'Receipt lost lineage or duplicated stock';end if;
 if (select received_qty from public.stock_transfers where id=f.transfer)<>2 then raise exception 'Shortage not recorded';end if;
 if exists(select 1 from public.inventory_purchases where branch_id=f.b) then raise exception 'Transfer created purchase spending';end if;
end $$;
reset role;
select set_config('request.jwt.claim.sub',staff::text,true) from lot_fixture;
set local role authenticated;
do $$declare f record;begin select * into f from lot_fixture;
 if exists(select 1 from public.inventory_transfer_lots) then raise exception 'Staff read transfer prices';end if;
 begin perform public.post_lot_transfer(f.a,f.transfer,gen_random_uuid(),'send','[]','Staff attempt');raise exception 'Staff mutated lots';exception when insufficient_privilege then null;end;
 raise notice 'PASS: lot dispatch/receipt, retry safety, shortage, expiry lineage, atomic rollback, staff and branch guards';
end $$;
reset role;
rollback;
